{"t":"say","text":"I'll draw a fully serverless REST API using Function Compute behind an API Gateway, with Tair for caching and RDS for data."}
{"t":"plan","products":["mobile-app","dns","cloud-native-api-gateway","fc","tair","rds","sls"]}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"assume","id":"auth","text":"API key authentication at gateway","alt":"OAuth2 / JWT validation"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"app","product":"mobile-app","label":"Mobile app","group":"internet","why":"End users calling the REST API from their devices."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the API domain to the gateway endpoint."}
{"t":"edge","id":"e-app-dns","from":"app","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"API VPC","parent":"sg"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","why":"Managed ingress with rate limiting, auth and routing to FC."}
{"t":"edge","id":"e-app-gateway","from":"app","to":"gateway","label":"HTTPS"}
{"t":"node","id":"api","product":"fc","label":"API functions","group":"vpc","why":"Serverless compute that scales instantly on spikes, pay per request."}
{"t":"edge","id":"e-gateway-api","from":"gateway","to":"api","label":"HTTP"}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Caches hot responses and sessions to reduce database load."}
{"t":"edge","id":"e-api-cache","from":"api","to":"cache","label":"Redis"}
{"t":"node","id":"db","product":"rds","label":"Primary DB","group":"vpc","zones":["a","b"],"why":"Stores persistent application data with high availability."}
{"t":"edge","id":"e-api-db","from":"api","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects function logs and metrics for monitoring and debugging."}
{"t":"edge","id":"e-api-logs","from":"api","to":"logs","kind":"control"}
{"t":"ask","id":"db-engine","text":"Which database engine do you prefer?","options":["MySQL","PostgreSQL","MongoDB"]}
{"t":"ask","id":"traffic-scale","text":"What is the expected peak requests per second during spikes?","options":["Under 1k","1k - 10k","Over 10k"]}
{"t":"done","summary":"Serverless REST API using Cloud-native API Gateway routing to Function Compute, with Tair caching and RDS storage."}

{"t":"say","text":"I'll design a highly available web architecture in Singapore with ESA, ALB, WAF, auto-scaling ECS, Tair cache and PolarDB."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","polardb","oss","sls","cloudmonitor"]}
{"t":"assume","id":"region","text":"Singapore region for Southeast Asia users","alt":"Kuala Lumpur or Jakarta"}
{"t":"assume","id":"peaks","text":"Auto Scaling handles big sales peaks","alt":"Fixed large fleet"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers","group":"internet","why":"30k daily users browsing the store."}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"Resolves store domain to ESA edge."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches static assets and accelerates dynamic requests across SEA."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Store VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Distributes traffic across two zones for high availability."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects against OWASP attacks and bot abuse during sales."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs the store backend across two zones."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Scales instances up during big sales peaks automatically."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app","label":"HTTP"}
{"t":"say","text":"Adding session cache, database, object storage and monitoring for full HA."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Stores sessions and hot product data with zone-level HA."}
{"t":"node","id":"db","product":"polardb","label":"PolarDB","group":"vpc","zones":["a","b"],"why":"Cloud-native DB with instant read scale-out for sales peaks."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache","label":"Redis"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Product images","group":"sg","why":"Stores product images and static assets served via ESA."}
{"t":"edge","id":"e-esa-media","from":"esa","to":"media","label":"assets"}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Centralizes application and access logs for troubleshooting."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"node","id":"monitor","product":"cloudmonitor","label":"CloudMonitor","group":"sg","why":"Monitors resource metrics and triggers alarms during peaks."}
{"t":"edge","id":"e-monitor-app","from":"monitor","to":"app","kind":"control"}
{"t":"ask","id":"payment-gateway","text":"Do you need a third-party payment gateway integration?","options":["Yes, external payment API","No, handled elsewhere"]}
{"t":"ask","id":"search-feature","text":"Does your store need full-text product search?","options":["Yes, add Elasticsearch","No, SQL queries are enough"]}
{"t":"done","summary":"Highly available online store in Singapore with ESA, ALB+WAF, auto-scaling ECS across 2 zones, Tair cache and PolarDB."}

{"t":"say","text":"I'll draw an ACK cluster for your 20 Java microservices with MSE for discovery, a Cloud-native API Gateway, RocketMQ, Tair and PolarDB."}
{"t":"plan","products":["users","dns","alb","cloud-native-api-gateway","ack","mse","rocketmq","tair","polardb","acr","sls","arms"]}
{"t":"assume","id":"exposure","text":"Public-facing services","alt":"Internal only"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Users","group":"internet","why":"Clients calling the microservices."}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"Resolves domain to the ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Microservices VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Ingress load balancer across two zones."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"Cloud-native API Gateway","group":"vpc","zones":["a","b"],"why":"Single API entry point with auth and routing."}
{"t":"edge","id":"e-alb-gateway","from":"alb","to":"gateway"}
{"t":"node","id":"ack","product":"ack","label":"ACK Cluster","group":"vpc","zones":["a","b"],"why":"Runs the 20 Java microservices as pods."}
{"t":"edge","id":"e-gateway-ack","from":"gateway","to":"ack","label":"HTTP/gRPC"}
{"t":"node","id":"mse","product":"mse","label":"MSE Nacos","group":"vpc","zones":["a","b"],"why":"Service discovery and config for all 20 services."}
{"t":"edge","id":"e-ack-mse","from":"ack","to":"mse","label":"discovery","kind":"control"}
{"t":"node","id":"mq","product":"rocketmq","label":"ApsaraMQ for RocketMQ","group":"vpc","zones":["a","b"],"why":"Async messaging between microservices."}
{"t":"edge","id":"e-ack-mq","from":"ack","to":"mq","label":"events","kind":"async"}
{"t":"node","id":"cache","product":"tair","label":"Tair Cache","group":"vpc","zones":["a","b"],"why":"In-memory cache for hot data and sessions."}
{"t":"edge","id":"e-ack-cache","from":"ack","to":"cache","label":"Redis"}
{"t":"node","id":"db","product":"polardb","label":"PolarDB","group":"vpc","zones":["a","b"],"why":"Relational database with compute-storage separation."}
{"t":"edge","id":"e-ack-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"acr","product":"acr","label":"Container Registry","group":"sg","why":"Stores container images for the 20 services."}
{"t":"edge","id":"e-acr-ack","from":"acr","to":"ack","label":"images","kind":"control"}
{"t":"node","id":"logs","product":"sls","label":"Simple Log Service","group":"sg","why":"Centralized log collection and analysis."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"node","id":"monitor","product":"arms","label":"ARMS","group":"sg","why":"APM and tracing for Java microservices."}
{"t":"edge","id":"e-ack-monitor","from":"ack","to":"monitor","kind":"control"}
{"t":"ask","id":"team-k8s","text":"Does your team already have Kubernetes experience?","options":["Yes, experienced with K8s","No, prefer serverless containers"]}
{"t":"ask","id":"db-engine","text":"Which relational engine do you prefer?","options":["MySQL-compatible","PostgreSQL-compatible"]}
{"t":"done","summary":"ACK cluster behind ALB and API Gateway, with MSE Nacos, RocketMQ, Tair, PolarDB, ACR, SLS and ARMS."}

{"t":"say","text":"I'll draw a private RAG assistant on ACK with Dify, Qwen models and a vector store over your policy docs."}
{"t":"plan","products":["users","alb","ack","dify-on-ack","oss","milvus","model-studio","nat","sls"]}
{"t":"assume","id":"deploy","text":"Self-hosted on ACK using Dify for the RAG pipeline","alt":"Build custom RAG code from scratch"}
{"t":"assume","id":"scale","text":"About 500 internal employees","alt":"Over 5000 employees"}
{"t":"group","id":"internal","kind":"external","label":"Internal network","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internal","why":"Staff asking policy and wiki questions."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Assistant VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"Internal ALB","group":"vpc","zones":["a","b"],"why":"Private load balancer exposing Dify to staff only."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"ack","product":"ack","label":"ACK cluster","group":"vpc","zones":["a","b"],"why":"Runs Dify and embedding workers."}
{"t":"node","id":"dify","product":"dify-on-ack","label":"Dify RAG app","group":"vpc","attachTo":"ack","why":"Low-code agent builder ingesting policies and answering questions."}
{"t":"edge","id":"e-alb-ack","from":"alb","to":"ack","label":"HTTP"}
{"t":"say","text":"Documents live in OSS, embeddings in Milvus, and Qwen calls go out through NAT."}
{"t":"node","id":"docs","product":"oss","label":"Policy documents","group":"sg","why":"Stores uploaded wiki pages and PDFs for ingestion."}
{"t":"edge","id":"e-ack-docs","from":"ack","to":"docs","label":"read/write"}
{"t":"node","id":"vector","product":"milvus","label":"Vector store","group":"vpc","zones":["a","b"],"why":"Holds document embeddings for fast retrieval."}
{"t":"edge","id":"e-ack-vector","from":"ack","to":"vector","label":"query"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Hosted Qwen models for generation and embedding."}
{"t":"edge","id":"e-ack-llm","from":"ack","to":"llm","label":"API"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Gives ACK outbound access to Model Studio APIs."}
{"t":"edge","id":"e-ack-nat","from":"ack","to":"nat","kind":"control"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects chat logs and system traces."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"ask","id":"wiki-source","text":"Where are your wiki and policy documents stored today?","options":["Files we will upload to OSS","Confluence or Notion","SharePoint or OneDrive"]}
{"t":"ask","id":"auth-method","text":"How should employees authenticate to the assistant?","options":["Corporate SSO via IDaaS","No login, network-only access"]}
{"t":"done","summary":"Internal RAG assistant on ACK with Dify, OSS for docs, Milvus for vectors and Model Studio for Qwen."}

{"t":"say","text":"I'll draw a data platform that replicates MySQL in real time via DTS, runs nightly batch in MaxCompute, and serves dashboards with Hologres and Quick BI."}
{"t":"plan","products":["users","rds","dts","maxcompute","dataworks","hologres","quick-bi","oss","sls"]}
{"t":"assume","id":"source-db","text":"MySQL order database already runs on Alibaba Cloud RDS","alt":"On-premises or other-cloud MySQL"}
{"t":"assume","id":"region","text":"Singapore region for all workloads","alt":"Another international region"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Data Platform VPC","parent":"sg"}
{"t":"node","id":"rds","product":"rds","label":"MySQL Orders DB","group":"vpc","zones":["a","b"],"why":"Source transactional database storing orders."}
{"t":"node","id":"dts","product":"dts","label":"DTS Real-time Sync","group":"sg","why":"Streams CDC changes from RDS to the warehouse."}
{"t":"edge","id":"e-rds-dts","from":"rds","to":"dts","label":"CDC","kind":"data"}
{"t":"node","id":"maxcompute","product":"maxcompute","label":"MaxCompute Warehouse","group":"sg","why":"Stores historical data and runs nightly batch analytics."}
{"t":"edge","id":"e-dts-maxcompute","from":"dts","to":"maxcompute","label":"sync","kind":"data"}
{"t":"node","id":"dataworks","product":"dataworks","label":"DataWorks Scheduler","group":"sg","why":"Orchestrates nightly ETL jobs over MaxCompute."}
{"t":"edge","id":"e-dataworks-maxcompute","from":"dataworks","to":"maxcompute","label":"nightly ETL","kind":"control"}
{"t":"node","id":"hologres","product":"hologres","label":"Hologres Serving","group":"vpc","why":"Interactive query engine serving dashboard requests fast."}
{"t":"edge","id":"e-maxcompute-hologres","from":"maxcompute","to":"hologres","label":"batch load","kind":"data"}
{"t":"node","id":"quickbi","product":"quick-bi","label":"Quick BI Dashboards","group":"sg","why":"Business dashboards querying Hologres directly."}
{"t":"edge","id":"e-hologres-quickbi","from":"hologres","to":"quickbi","label":"SQL","kind":"data"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Business Users","group":"internet","why":"Staff viewing reports and dashboards."}
{"t":"edge","id":"e-users-quickbi","from":"users","to":"quickbi","label":"HTTPS"}
{"t":"node","id":"oss","product":"oss","label":"Data Lake Storage","group":"sg","why":"Landing zone for raw files and external data."}
{"t":"edge","id":"e-oss-maxcompute","from":"oss","to":"maxcompute","label":"ingest","kind":"data"}
{"t":"node","id":"sls","product":"sls","label":"SLS Logs","group":"sg","why":"Central logging for pipeline monitoring and alerts."}
{"t":"edge","id":"e-dataworks-sls","from":"dataworks","to":"sls","kind":"control"}
{"t":"ask","id":"source-location","text":"Where does your source MySQL database run today?","options":["Alibaba Cloud RDS","On-premises","AWS / Azure / GCP"]}
{"t":"ask","id":"latency-need","text":"How fresh must the dashboard data be?","options":["Real-time (seconds)","Hourly micro-batch","Nightly only"]}
{"t":"done","summary":"Data platform replicating MySQL via DTS into MaxCompute, orchestrated by DataWorks, served through Hologres and Quick BI dashboards."}

{"t":"say","text":"I'll draw a real-time IoT telemetry pipeline: devices to IoT Platform, Flink for anomaly detection, alerts via EventBridge, and DataV dashboards."}
{"t":"plan","products":["iot-devices","iot-platform","kafka","flink","eventbridge","sms","tablestore","hologres","datav","sls"]}
{"t":"assume","id":"region","text":"Deployed in Singapore","alt":"Another region"}
{"t":"assume","id":"protocol","text":"Devices use MQTT protocol","alt":"HTTPS or CoAP"}
{"t":"group","id":"field","kind":"external","label":"Field","parent":null}
{"t":"node","id":"devices","product":"iot-devices","label":"100k IoT devices","group":"field","why":"Sends telemetry every few seconds."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"IoT VPC","parent":"sg"}
{"t":"node","id":"iot","product":"iot-platform","label":"IoT Platform","group":"sg","why":"Ingests and routes device telemetry at scale."}
{"t":"edge","id":"e-devices-iot","from":"devices","to":"iot","label":"MQTT","kind":"data"}
{"t":"node","id":"kafka","product":"kafka","label":"Kafka","group":"vpc","why":"Buffers high-throughput telemetry for streaming."}
{"t":"edge","id":"e-iot-kafka","from":"iot","to":"kafka","label":"telemetry","kind":"async"}
{"t":"node","id":"flink","product":"flink","label":"Flink","group":"vpc","why":"Detects anomalies on telemetry in real time."}
{"t":"edge","id":"e-kafka-flink","from":"kafka","to":"flink","label":"stream","kind":"data"}
{"t":"node","id":"events","product":"eventbridge","label":"EventBridge","group":"sg","why":"Routes anomaly events to alert targets."}
{"t":"edge","id":"e-flink-events","from":"flink","to":"events","label":"anomalies","kind":"async"}
{"t":"node","id":"sms","product":"sms","label":"SMS alerts","group":"sg","why":"Notifies operators of detected anomalies."}
{"t":"edge","id":"e-events-sms","from":"events","to":"sms","label":"alert","kind":"async"}
{"t":"node","id":"tsdb","product":"tablestore","label":"Tablestore","group":"sg","why":"Stores raw telemetry at massive scale cheaply."}
{"t":"edge","id":"e-flink-tsdb","from":"flink","to":"tsdb","label":"write","kind":"data"}
{"t":"node","id":"olap","product":"hologres","label":"Hologres","group":"vpc","why":"Serves aggregated metrics for the dashboard."}
{"t":"edge","id":"e-flink-olap","from":"flink","to":"olap","label":"metrics","kind":"data"}
{"t":"node","id":"dash","product":"datav","label":"DataV dashboard","group":"sg","why":"Live visualization of telemetry and anomalies."}
{"t":"edge","id":"e-olap-dash","from":"olap","to":"dash","label":"query","kind":"data"}
{"t":"node","id":"logs","product":"sls","label":"SLS","group":"sg","why":"Centralizes pipeline logs and audit trails."}
{"t":"edge","id":"e-flink-logs","from":"flink","to":"logs","kind":"control"}
{"t":"ask","id":"alert-channel","text":"Besides SMS, do you need alerts sent to DingTalk, email or webhooks?","options":["SMS only","DingTalk + SMS","Email + SMS","Webhook + SMS"]}
{"t":"ask","id":"retention","text":"How long must raw telemetry be retained for compliance or analysis?","options":["7 days","30 days","1 year","Over 1 year"]}
{"t":"done","summary":"Real-time IoT pipeline: IoT Platform ingests from 100k devices, Kafka buffers, Flink detects anomalies, Tablestore stores raw data, Hologres serves DataV dashboards, and EventBridge triggers SMS alerts."}

{"t":"say","text":"I'll draw your Singapore data center connected to Alibaba Cloud via Express Connect, with SMC and DTS for step-by-step VM and database migration."}
{"t":"plan","products":["onprem-dc","express-connect","vpc","ecs","smc","dts","sls"]}
{"t":"assume","id":"migration-scope","text":"VMs and databases migrate incrementally","alt":"Only VMs migrate"}
{"t":"group","id":"onprem","kind":"onprem","label":"Singapore On-Premises DC","parent":null}
{"t":"node","id":"onprem-dc","product":"onprem-dc","label":"On-premises servers","group":"onprem","why":"Existing VMs and databases to migrate step by step."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Cloud VPC","parent":"sg"}
{"t":"node","id":"target-vms","product":"ecs","label":"Migrated ECS instances","group":"vpc","zones":["a","b"],"why":"Destination VMs receiving workloads from on-premises."}
{"t":"node","id":"smc","product":"smc","label":"Server Migration Center","group":"sg","why":"Incrementally copies on-premises VMs to ECS."}
{"t":"node","id":"dts","product":"dts","label":"Data Transmission Service","group":"sg","why":"Syncs databases from on-premises to cloud during cutover."}
{"t":"edge","id":"e-onprem-smc","from":"onprem-dc","to":"smc","label":"VM sync"}
{"t":"edge","id":"e-smc-target","from":"smc","to":"target-vms","label":"deploy"}
{"t":"edge","id":"e-onprem-dts","from":"onprem-dc","to":"dts","label":"DB sync"}
{"t":"edge","id":"e-dts-target","from":"dts","to":"target-vms","label":"data"}
{"t":"say","text":"Express Connect provides the private dedicated link between your data center and the cloud VPC."}
{"t":"node","id":"link","product":"express-connect","label":"Express Connect","group":"vpc","why":"Private dedicated line linking on-premises network to VPC."}
{"t":"edge","id":"e-onprem-link","from":"onprem-dc","to":"link","label":"private"}
{"t":"node","id":"logs","product":"sls","label":"Migration logs","group":"sg","why":"Tracks migration progress and errors centrally."}
{"t":"edge","id":"e-smc-logs","from":"smc","to":"logs","kind":"control"}
{"t":"ask","id":"db-type","text":"Which databases are you migrating?","options":["MySQL or PostgreSQL","SQL Server","MongoDB","No databases"]}
{"t":"ask","id":"vm-count","text":"Roughly how many VMs need migration?","options":["Under 20","20 to 100","Over 100"]}
{"t":"done","summary":"On-premises Singapore DC linked to Alibaba Cloud VPC via Express Connect, with SMC for VM migration and DTS for database sync."}

{"t":"say","text":"I'll draw an e-sports streaming platform using ApsaraVideo Live, VOD, ESA for edge delivery, and OSS for media storage."}
{"t":"plan","products":["users","dns","esa","live","vod","mps","oss","cdn","ecs","alb","rds","tair","sls"]}
{"t":"assume","id":"scale","text":"About 50k concurrent viewers","alt":"Over 500k concurrent viewers"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Multi-region delivery"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"E-sports fans","group":"internet","why":"Viewers watching live streams and VOD content."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves platform domains to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates web UI and protects against DDoS and bots."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"node","id":"cdn","product":"cdn","label":"CDN","group":"edge","why":"Delivers live streams and VOD playback to fans globally."}
{"t":"edge","id":"e-users-cdn","from":"users","to":"cdn","label":"stream"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Platform VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes API and web traffic across zones."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs platform APIs, user auth and stream metadata."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Caches sessions and hot stream metadata."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"node","id":"db","product":"rds","label":"Platform DB","group":"vpc","zones":["a","b"],"why":"Stores users, channels and VOD catalog."}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"say","text":"Now adding the media pipeline: Live ingest, VOD, transcoding and object storage."}
{"t":"node","id":"live","product":"live","label":"ApsaraVideo Live","group":"sg","why":"Ingests and transcodes e-sports live streams."}
{"t":"edge","id":"e-live-cdn","from":"live","to":"cdn","label":"push"}
{"t":"node","id":"vod","product":"vod","label":"ApsaraVideo VOD","group":"sg","why":"Manages VOD uploads, transcoding and playback."}
{"t":"edge","id":"e-vod-cdn","from":"vod","to":"cdn","label":"push"}
{"t":"node","id":"mps","product":"mps","label":"Media Processing","group":"sg","why":"Transcodes and adds watermarks to highlight clips."}
{"t":"edge","id":"e-live-mps","from":"live","to":"mps","label":"clips"}
